contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        address beforeOwner = c.owner();
        require(caller == beforeOwner || caller != beforeOwner, "caller arbitrary");
        bool reverted;
        // The test contract is the owner from the fresh deployment.
        // If caller is not the test contract, we cannot make the call as that caller;
        // we can only drive the deciding call through transferOwnership from the test contract.
        // To test the non-owner branch, we first transfer ownership away from the test contract
        // (if newOwner is not the test contract), then attempt a second call as the (now non-owner) test contract.
        if (caller != address(this)) {
            // caller is arbitrary; we cannot impersonate, so use the test contract as caller.
            // The focus is on transferOwnership's effect on owner.
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            if (!reverted) {
                assert(afterOwner == newOwner);
            } else {
                assert(afterOwner == beforeOwner);
            }
        } else {
            // caller == address(this): test contract is the current owner (fresh deployment).
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address afterOwner = c.owner();
            if (!reverted) {
                assert(afterOwner == newOwner);
            } else {
                assert(afterOwner == beforeOwner);
            }
        }
    }
}

