contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        // Read the owner before the deciding call. Since this contract deployed c,
        // msg.sender for every call on c is this contract. To exercise both the
        // owner and non-owner branches we set up ownership so this contract is the
        // owner, then transfer away to a non-zero address if needed.
        address ownerBefore = c.owner();

        // Setup target: make sure the test contract is NOT the owner of c, so the
        // deciding call below is made by a non-owner. We do this with flat,
        // top-level state-changing calls on c.
        if (ownerBefore == address(this)) {
            // Move ownership away so the next call is non-owner.
            c.transferOwnership(address(0xdeadbeef));
        }

        // Re-read owner just before the deciding call; each call is its own
        // top-level statement, and the reads are view calls.
        address ownerBeforeCall = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: the call succeeds exactly when the caller is the owner
        // before the call; on success owner becomes newOwner, on revert owner is
        // unchanged.
        if (reverted) {
            assert(ownerBeforeCall == ownerAfter);
        } else {
            assert(ownerAfter == newOwner);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        // This contract deployed c, so msg.sender for c calls is this contract.
        // If this contract is not yet the owner, become the owner via the public
        // transferOwnership entry (only works if this contract is the owner, so
        // we only call it when our stored ownerBefore equals address(this)).
        address ownerBefore = c.owner();

        // Setup: if this contract is already the owner, leave it so the deciding
        // call below is an owner call. If it is not the owner, we cannot make
        // ourselves the owner through c's public surface (no setter without
        // being owner), so the deciding call will be a non-owner call.

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // Exactly one assert. General rule: the transfer succeeds exactly when
        // the caller is the owner before the call; on success owner becomes
        // newOwner, on revert owner is unchanged.
        assert(
            (reverted && ownerAfter == ownerBefore) ||
            (!reverted && ownerAfter == newOwner)
        );
    }

    receive() external payable {}
}

